import{_ as e}from"./chunks/X25-EVO.BLINERX1.js";import{_ as a,c as r,o as l,al as i}from"./chunks/framework.CT7RwC5a.js";const b=JSON.parse('{"title":"CUAV X25-EVO","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_controller/cuav_x25-evo.md","filePath":"zh/flight_controller/cuav_x25-evo.md"}'),o={name:"zh/flight_controller/cuav_x25-evo.md"};function n(s,t,d,u,h,c){return l(),r("div",null,t[0]||(t[0]=[i('<h1 id="cuav-x25-evo" tabindex="-1">CUAV X25-EVO <a class="header-anchor" href="#cuav-x25-evo" aria-label="Permalink to &quot;CUAV X25-EVO&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>X25-EVO</em> is an advanced autopilot manufactured by CUAV<sup>®</sup>.</p><p>The autopilot is recommended for commercial system integration but is also suitable for academic research and any other applications.</p><p><img src="'+e+'" alt="X25-EVO AutoPilot - hero image"></p><p>The X25-EVO brings you ultimate performance, stability, and reliability in every aspect.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These flight controllers are <a href="./../flight_controller/autopilot_manufacturer_supported.html">manufacturer supported</a>.</p></div><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>Arm® Cortex-M7® processor (STM32H743XI) with Floating-Point Unit (FPU), operating at 480MHz, and featuring 2MB Flash memory. Enables developers to enhance productivity and efficiency, allowing for more complex algorithms and models.</li><li>Automotive-grade RM3100 compass. Designed for better stability and anti-interference capability.</li><li>Triple-redundant IMUs and dual-redundant barometers located on separate buses. If the PX4 autopilot detects a sensor failure, the system seamlessly switches to another sensor to maintain flight control reliability.</li><li>Independent LDO power control supplies power to each sensor group. A vibration isolation system filters high-frequency vibrations and reduces noise to ensure accurate readings, enabling better overall flight performance for the vehicle.</li><li>Integrated Microchip Ethernet PHY for high-speed communication with onboard devices like mission computers via Ethernet.</li><li>Dual temperature compensation systems, located on the IMU board and FMU board respectively. Temperature is controlled by onboard heating resistors to achieve the optimal operating temperature for the IMUs.</li><li>PWM servo output voltage switchable between 3.3V or 5V.</li><li>Modular design for DIY carrier boards.</li></ul><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>Main Processor: STM32H743XI <ul><li>32-bit Arm® Cortex®-M7, 480MHz, 2MB Flash, 1MB RAM</li></ul></li><li>Onboard Sensors: <ul><li>Accel/Gyro: IIM42652*2</li><li>Accel/Gyro: IIM42653</li><li>Magnetometer: RM3100</li><li>Barometer: BMP581</li><li>Barometer: ICP-20100</li></ul></li></ul><h3 id="electrical-data" tabindex="-1">Electrical Data <a class="header-anchor" href="#electrical-data" aria-label="Permalink to &quot;Electrical Data&quot;">​</a></h3><ul><li>Rated Voltage: <ul><li>Input Voltage: 10~18V</li><li>USB 电源输入：4.75~5.25V</li><li>Servo Rail Input: 0~9.9V</li></ul></li><li>Rated Current: <ul><li>Total Output Max Current: 10A</li><li>TELEM1 and TELEM2 Output Current limiter: 4A</li><li>CAN1 and CAN2 Output Current limiter: 2.4A</li><li>Other Ports Output Current limiter: 1.5A</li></ul></li></ul><h3 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h3><ul><li>16x PWM Servo Outputs</li><li>1x Dedicated R/C Input for Spektrum / DSM and S.Bus</li><li>1x Analog/PWM RSSI Input</li><li>2x TELEM Ports (with full flow control)</li><li>1x UART4 Port</li><li>2x GPS Ports <ul><li>1x Full GPS plus Safety Switch Port (GPS1)</li><li>1x Basic GPS Port (with I2C, GPS2)</li></ul></li><li>1x USB Port (TYPE-C)</li><li>1x Ethernet Port <ul><li>Transformerless application</li><li>100Mbps</li></ul></li><li>3x I2C Bus Ports</li><li>1x SPI Bus <ul><li>1x Chip Select Line</li><li>1x Data Ready Line</li><li>1x SPI Reset Line</li></ul></li><li>5x CAN Ports for CAN Peripherals <ul><li>3x CAN1 Bus Multiplexed Ports</li><li>2x CAN2 Bus Multiplexed Ports</li></ul></li><li>2x Power Input Ports <ul><li>DroneCAN/UAVCAN Power Input</li></ul></li><li>2x AD Ports <ul><li>Analog Input (3.3V)</li><li>Analog Input (6.6V - not supported by PX4)</li></ul></li><li>1x Dedicated Debug Port <ul><li>FMU Debug</li></ul></li></ul><h3 id="mechanical-data" tabindex="-1">Mechanical Data <a class="header-anchor" href="#mechanical-data" aria-label="Permalink to &quot;Mechanical Data&quot;">​</a></h3><ul><li>Not provided.</li></ul><h2 id="purchase-channels" tabindex="-1">Purchase Channels <a class="header-anchor" href="#purchase-channels" aria-label="Permalink to &quot;Purchase Channels&quot;">​</a></h2><p>Order from <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">CUAV</a>.</p><h2 id="组装-设置" tabindex="-1">组装 / 设置 <a class="header-anchor" href="#组装-设置" aria-label="Permalink to &quot;组装 / 设置&quot;">​</a></h2><ul><li>Not provided.</li></ul><h2 id="pin-definitions" tabindex="-1">Pin Definitions <a class="header-anchor" href="#pin-definitions" aria-label="Permalink to &quot;Pin Definitions&quot;">​</a></h2><ul><li>Not provided.</li></ul><h2 id="串口映射" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射" aria-label="Permalink to &quot;串口映射&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>Debug Console</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr></tbody></table><h2 id="额定电压" tabindex="-1">额定电压 <a class="header-anchor" href="#额定电压" aria-label="Permalink to &quot;额定电压&quot;">​</a></h2><p>The <em>X25-EVO</em> achieves triple redundancy on power supplies if three power sources are provided. The three power rails are POWERC1, POWERC2, and USB.</p><ul><li><strong>POWER C1</strong> and <strong>POWER C2</strong> are DroneCAN/UAVCAN battery interfaces.</li></ul><p><strong>Normal Operation Maximum Ratings</strong></p><p>Under these conditions, all power sources will be used to power the system in the following order:</p><ol><li><strong>POWER C1</strong> and <strong>POWER C2</strong> Inputs (10V to 18V)</li><li>USB Input (4.75V to 5.25V)</li></ol><p><strong>Voltage monitoring</strong></p><p>Digital DroneCAN/UAVCAN battery monitoring is enabled by default.</p><h2 id="编译固件" tabindex="-1">编译固件 <a class="header-anchor" href="#编译固件" aria-label="Permalink to &quot;编译固件&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users do not need to build this firmware! It is pre-built and installed automatically by <em>QGroundControl</em> when the appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target, execute:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make cuav_x25-evo_default</span></span></code></pre></div><p><a id="debug_port"></a></p><h2 id="调试接口" tabindex="-1">调试接口 <a class="header-anchor" href="#调试接口" aria-label="Permalink to &quot;调试接口&quot;">​</a></h2><p>The <a href="./../debug/system_console.html">PX4 System Console</a> and <a href="./../debug/swd_debug.html">SWD Interface</a> operate on the <strong>FMU Debug</strong> port.</p><table tabindex="0"><thead><tr><th>针脚</th><th>信号</th><th>电压</th></tr></thead><tbody><tr><td>1（红）</td><td>5V+</td><td>+5V</td></tr><tr><td>2</td><td>DEBUG TX (OUT)</td><td>+3.3V</td></tr><tr><td>3</td><td>DEBUG RX (IN)</td><td>+3.3V</td></tr><tr><td>4（黑）</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>6</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>6</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="支持的平台-机身" tabindex="-1">支持的平台/机身 <a class="header-anchor" href="#支持的平台-机身" aria-label="Permalink to &quot;支持的平台/机身&quot;">​</a></h2><p>Any multirotor/airplane/rover or boat that can be controlled using normal RC servos or Futaba S-Bus servos. The complete set of supported configurations can be found in the <a href="./../airframes/airframe_reference.html">Airframe Reference</a>.</p><h2 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to &quot;更多信息&quot;">​</a></h2><ul><li><a href="https://doc.cuav.net/" target="_blank" rel="noreferrer">CUAV Docs</a></li></ul>',45)]))}const f=a(o,[["render",n]]);export{b as __pageData,f as default};
